module power_segment_counter(\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] arr_0, arr_1, arr_2, arr_3, arr_4, arr_5, arr_6, arr_7,\n    input [3:0] len,\n    input signed [3:0] k,\n    output reg [15:0] result,\n    output reg done\n);\n    // State declarations\n    localparam [3:0] S_IDLE = 4'd0;\n    localparam [3:0] S_ADD = 4'd1;\n    localparam [3:0] S_CHECK_POWER = 4'd2;\n    localparam [3:0] S_CHECK_POWER_LOOP = 4'd3;\n    localparam [3:0] S_CHECK_POWER_END = 4'd4;\n    localparam [3:0] S_NEXT_J = 4'd5;\n    localparam [3:0] S_NEXT_I = 4'd6;\n    localparam [3:0] S_DONE = 4'd7;\n    \n    reg [3:0] state;\n    reg [3:0] i, j;\n    reg signed [15:0] sum;\n    reg signed [15:0] p;\n    reg found;\n    reg [15:0] count;\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= S_IDLE;\n            i <= 4'd0;\n            j <= 4'd0;\n            sum <= 16'sd0;\n            p <= 16'sd0;\n            found <= 1'b0;\n            count <= 16'd0;\n            result <= 16'd0;\n            done <= 1'b0;\n        end else begin\n            case (state)\n                S_IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        i <= 4'd0;\n                        j <= 4'd0;\n                        sum <= 16'sd0;\n                        count <= 16'd0;\n                        state <= S_ADD;\n                    end\n                end\n                \n                S_ADD: begin\n                    if (j < len) begin\n                        sum <= sum + $signed({{8{arr_7[7]}}, arr_7});  // Sign-extend arr[j]\n                        state <= S_CHECK_POWER;\n                    end else begin\n                        state <= S_NEXT_I;\n                    end\n                end\n                \n                S_CHECK_POWER: begin\n                    if (k == 4'sd1) begin\n                        found <= (sum == 16'sd1);\n                        state <= S_CHECK_POWER_END;\n                    end else if (k == -4'sd1) begin\n                        found <= (sum == 16'sd1) || (sum == -16'sd1);\n                        state <= S_CHECK_POWER_END;\n                    end else begin\n                        p <= 16'sd1;\n                        state <= S_CHECK_POWER_LOOP;\n                    end\n                end\n                \n                S_CHECK_POWER_LOOP: begin\n                    if ((p[15] && (-p > 16'sd1016)) || (!p[15] && (p > 16'sd1016))) begin\n                        found <= 1'b0;\n                        state <= S_CHECK_POWER_END;\n                    end else if (p == sum) begin\n                        found <= 1'b1;\n                        state <= S_CHECK_POWER_END;\n                    end else begin\n                        p <= p * $signed({{12{k[3]}}, k});  // Sign-extend k to 16 bits\n                    end\n                end\n                \n                S_CHECK_POWER_END: begin\n                    if (found) count <= count + 16'd1;\n                    j <= j + 4'd1;\n                    if (j < len - 4'd1) begin\n                        state <= S_ADD;\n                    end else begin\n                        i <= i + 4'd1;\n                        if (i < len - 4'd1) begin\n                            j <= i + 4'd1;\n                            sum <= 16'sd0;\n                            state <= S_ADD;\n                        end else begin\n                            state <= S_DONE;\n                        end\n                    end\n                end\n                \n                S_DONE: begin\n                    result <= count;\n                    done <= 1'b1;\n                    state <= S_IDLE;\n                end\n                \n                default: begin\n                    state <= S_IDLE;\n                end\n            endcase\n        end\n    end\n\n    // Array element selection\n    wire [7:0] arr [0:7];\n    assign arr[0] = arr_0;\n    assign arr[1] = arr_1;\n    assign arr[2] = arr_2;\n    assign arr[3] = arr_3;\n    assign arr[4] = arr_4;\n    assign arr[5] = arr_5;\n    assign arr[6] = arr_6;\n    assign arr[7] = arr_7;\nendmodule